#include <string>
#include <vector>

class Solution {
public:
    int countWaysToFormTarget(std::string s1, std::string s2, std::string target) {
        long long MOD = 1000000007;
        int k = s1.size(), tLen = target.size();
        if (k < tLen) return 0;
        std::vector<std::vector<int>> colCounts(k, std::vector<int>(26, 0));
        for (int c = 0; c < k; ++c) {
            colCounts[c][s1[c] - 'a']++;
            colCounts[c][s2[c] - 'a']++;
        }
        std::vector<long long> dp(tLen + 1, 0);
        dp[0] = 1;
        for (int c = 0; c < k; ++c) {
            for (int j = std::min(c + 1, tLen); j >= 1; --j) {
                int ch = target[j - 1] - 'a';
                if (colCounts[c][ch] > 0) {
                    dp[j] = (dp[j] + dp[j - 1] * colCounts[c][ch]) % MOD;
                }
            }
        }
        return dp[tLen];
    }
};

class Solution {
    public int countWaysToFormTarget(String s1, String s2, String target) {
        long MOD = 1_000_000_007L;
        int k = s1.length(), tLen = target.length();
        if (k < tLen) return 0;
        int[][] colCounts = new int[k][26];
        for (int c = 0; c < k; c++) {
            colCounts[c][s1.charAt(c) - 'a']++;
            colCounts[c][s2.charAt(c) - 'a']++;
        }
        long[] dp = new long[tLen + 1];
        dp[0] = 1;
        for (int c = 0; c < k; c++) {
            for (int j = Math.min(c + 1, tLen); j >= 1; j--) {
                int ch = target.charAt(j - 1) - 'a';
                if (colCounts[c][ch] > 0) {
                    dp[j] = (dp[j] + dp[j - 1] * colCounts[c][ch]) % MOD;
                }
            }
        }
        return (int) dp[tLen];
    }
}

